/* MUTANT: one refusal broken on purpose. Generated by mut/make.py. */
/* <ov-player> - a media player that shows only what the media element can prove.
 *
 * Built around the same rule as <ov-transport> (no
 * duration, no seek bar) and the readout rule of the whole kit.
 *
 *   <ov-player label="CAM 2"><video src="..."><track kind="captions" ...></video></ov-player>
 *   <ov-player label="PAD" waveform><audio src="..."></audio></ov-player>
 *   <ov-player for="feed" label="DOWNLINK"></ov-player>
 *   player.media = someMediaLikeObject;   // anything shaped like HTMLMediaElement
 *
 * ⚠️ THE ELEMENT NEVER DECIDES WHAT THE MEDIA IS DOING. It reads paused,
 * readyState, currentTime, buffered, played, seekable, duration, volume,
 * muted, playbackRate, loop, textTracks, error and getVideoPlaybackQuality()
 * from the media it is given, and listens to the media's own events. Every
 * control ASKS the media; what the player then says comes back from it.
 *
 * ── THE CONTROLS ──────────────────────────────────────────────────────────
 *
 * Play / pause, back and forward 10 s, the seek bar (with a readout of what
 * is under the pointer), go to live, playback rate, loop, captions, mute and
 * volume, picture-in-picture and full screen, and the keyboard: space or K
 * play, J / L 10 s, arrows 5 s and volume, M mute, C captions, F full screen.
 *
 * A control that cannot work is ABSENT and says why, never inert: no caption
 * track reads NO CAPTIONS instead of a CC button that does nothing, no seekable
 * range removes the skip buttons with the bar, and picture-in-picture and full
 * screen appear only where the browser offers them.
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 A FRAME ON SCREEN IS NOT PLAYBACK. The player says PLAYING only when
 * play was asked for, the media has data past the current position
 * (readyState HAVE_FUTURE_DATA or better) and the clock has actually moved
 * within the last `freeze` seconds. Otherwise it names what it sees instead:
 *
 *   buffering       play asked for, not enough data (the media's `waiting`)
 *   stalled         buffering, and the network has stopped delivering
 *                   (the media's `stalled`, cleared by `progress`)
 *   frozen          enough data, not paused, and the clock is not moving
 *   picture-frozen  the clock is moving and no new video frame has been
 *                   counted for `freeze` seconds (getVideoPlaybackQuality)
 *   blocked         play() was refused (autoplay policy, NotAllowedError)
 *   held            playbackRate is 0
 *   seeking, paused, ended, error, empty, none
 *
 * In every one of those the pause glyph is not drawn, the playhead is dashed,
 * and a video under it is covered by a band that says what the picture is.
 *
 * And the rest that fall out of it:
 *
 * 1. BUFFERED IS NOT PLAYED. The bar draws the media's `played` ranges solid,
 *    its `buffered` ranges hatched, each range where it really is, gaps left
 *    empty. Hovering the bar says PLAYED, BUFFERED or NOT BUFFERED there.
 * 2. BEHIND THE LIVE EDGE IS NOT LIVE. LIVE is claimed only when the stream
 *    has no end, the position is within `live-tolerance` seconds of the end
 *    of the seekable range, playback is really PLAYING, and that edge has
 *    moved within three target durations. The distance from the edge is
 *    printed beside LIVE every time. With no seekable range the edge is LIVE
 *    EDGE UNKNOWN, and no claim is made.
 * 3. STALLS AND DROPPED FRAMES ARE COUNTED, NOT HIDDEN. Playback that had
 *    started and then stopped moving is a stall, counted with its time; the
 *    wait before playback begins and after a seek is shown but is not one.
 *    Dropped / total frames are printed as the media reports them, or FRAMES
 *    NOT REPORTED when it does not.
 * 4. A QUALIFIER IS NEVER DROPPED. A rate other than ×1 is printed beside the
 *    time, MUTED is a word, and a waveform is drawn only from the decoded file
 *    itself (WAVEFORM UNAVAILABLE when it cannot be read), never a stock one.
 *
 * `demo` marks the player as a demonstration on its face.
 *
 * Motion: NO ANIMATION FRAMES. The media's own events (timeupdate fires
 * every 15 to 250 ms while the clock moves) drive every redraw, and only
 * while the player is on screen. One timer, started through whenArrived(),
 * redraws at the moment a silence passes `freeze` seconds, so FROZEN is said
 * without anything ticking.
 */

import { define, whenArrived, watchSeen, isSeen } from '../../../src/ov-core.js';

const FREEZE_DEFAULT = 2;        // seconds without the clock moving
const TARGET_DEFAULT = 6;        // HLS target duration, seconds
const LIVE_SYNC_COUNT = 3;       // hls.js and the HLS spec: three target durations
const HAVE_FUTURE_DATA = 3;
const SKIP = 10;
const RATES = [0.5, 0.75, 1, 1.25, 1.5, 2];
const PEAKS = 400;
const EVENTS = ['loadstart', 'loadedmetadata', 'loadeddata', 'canplay', 'canplaythrough', 'play',
  'playing', 'pause', 'waiting', 'stalled', 'suspend', 'timeupdate', 'progress', 'seeking',
  'seeked', 'ended', 'error', 'emptied', 'durationchange', 'ratechange', 'volumechange', 'abort',
  'enterpictureinpicture', 'leavepictureinpicture'];

const WORD = {
  none: 'NO MEDIA',
  empty: 'NOTHING LOADED',
  error: 'MEDIA ERROR',
  ended: 'ENDED',
  blocked: 'PLAY REFUSED',
  seeking: 'SEEKING',
  paused: 'PAUSED',
  buffering: 'BUFFERING',
  stalled: 'STALLED',
  frozen: 'FROZEN',
  'picture-frozen': 'PICTURE FROZEN',
  held: 'RATE 0',
  playing: 'PLAYING',
};
const STALL_STATES = new Set(['buffering', 'stalled', 'frozen', 'picture-frozen']);
const ERRORS = { 1: 'ABORTED', 2: 'NETWORK', 3: 'DECODE', 4: 'SOURCE NOT SUPPORTED' };

export function clock(s) {
  if (!Number.isFinite(s)) return '-:--';
  const n = Math.max(0, Math.floor(s));
  const h = Math.floor(n / 3600);
  const m = Math.floor(n / 60) % 60;
  const sec = String(n % 60).padStart(2, '0');
  return h ? `${h}:${String(m).padStart(2, '0')}:${sec}` : `${m}:${sec}`;
}

/* A TimeRanges, or anything with its shape, as [[start, end], ...]. */
export function ranges(tr) {
  const out = [];
  if (!tr || typeof tr.length !== 'number') return out;
  for (let i = 0; i < tr.length; i++) {
    const a = Number(tr.start(i));
    const b = Number(tr.end(i));
    if (Number.isFinite(a) && Number.isFinite(b) && b > a) out.push([a, b]);
  }
  return out;
}
const inside = (list, t) => list.some(([a, b]) => t >= a && t <= b);
/* A wall-clock time. A silence is said by WHEN it began, never by a seconds
 * figure: nothing redraws during a stall, so a duration would stop counting
 * while the stall went on (found in a real browser: 1.4s shown for 13s). */
const hms = (ms) => new Date(ms).toTimeString().slice(0, 8);

/* Icons are NAMED here and DRAWN by the theme: tools/gen_player_icons.py writes
 * one skeleton per name through each theme's pen into player-icons.css. Each
 * state that differs in truth differs in FORM in every pen, and the generator
 * refuses a sheet where it does not: pause is never pending, captions on are
 * not captions off, muted is not sound. */

const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => { if (el && el.getAttribute(k) !== v) el.setAttribute(k, v); };
const pct = (v) => `${(Math.max(0, Math.min(1, v)) * 100).toFixed(3)}%`;
const rateText = (r) => `×${Number(r.toFixed(2))}`;

class OvPlayer extends HTMLElement {
  static observedAttributes = ['label', 'for', 'freeze', 'target-duration', 'live-tolerance', 'live', 'demo', 'waveform', 'controls'];

  /* Our clock, in epoch ms. Replaceable so a test can drive time. */
  static now = () => Date.now();

  /* The file itself, decoded: channel 0 and its length in seconds. Replaceable
   * so a test can hand over known samples (a headless browser on virtual time
   * never finishes a decode). Throws when the file cannot be read. */
  static decode = async (src) => {
    const res = await fetch(src);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const Ctx = window.OfflineAudioContext || window.webkitOfflineAudioContext;
    const audio = await new Ctx(1, 1, 44100).decodeAudioData(await res.arrayBuffer());
    return { data: audio.getChannelData(0), seconds: audio.duration };
  };

  constructor() {
    super();
    this._media = null;
    this._state = null;
    this._timer = null;
    this._wave = null;           // { src, d } once a file has been decoded
    this.resetTracking();
  }

  resetTracking() {
    this._intent = false;        // play has been asked for and not withdrawn
    this._blocked = false;       // play() was refused
    this._netStalled = false;    // the media's `stalled`, until `progress`
    this._lastTime = null;       // currentTime when last seen to change
    this._lastAdvance = null;    // when the clock last moved, or play last began
    this._frames = null;         // totalVideoFrames when last seen to change
    this._lastFrame = null;      // when a new frame was last counted
    this._edge = null;           // live edge when last seen to change
    this._lastEdge = null;       // when it last moved
    this._hasPlayed = false;     // PLAYING was said since play was last asked for or a seek
    this._stalls = 0;
    this._stallMs = 0;
    this._stallFrom = null;      // start of the open stall episode
  }

  connectedCallback() {
    if (!this._built) this.build();
    this._unseen = watchSeen(this, () => this.draw());
    this.bind();
    this.draw();
  }

  disconnectedCallback() {
    if (this._unseen) this._unseen();
    this._unseen = null;
    this.unbind();
    this.unschedule();
  }

  attributeChangedCallback(name) {
    if (!this.isConnected || !this._built) return;
    if (name === 'for') this.bind();
    if (name === 'waveform') this.loadWave();
    this.draw();
  }

  /* ---- the media ------------------------------------------------------ */

  get media() { return this._media; }

  set media(m) {
    this._explicit = m || null;
    if (this.isConnected) { this.bind(); this.draw(); }
  }

  findMedia() {
    if (this._explicit) return this._explicit;
    const id = this.getAttribute('for');
    if (id) return document.getElementById(id);
    return this.querySelector('.ov-player__frame > video, .ov-player__frame > audio');
  }

  bind() {
    const next = this.findMedia();
    if (next === this._media) return;
    this.unbind();
    this._media = next;
    this.resetTracking();
    if (!next || typeof next.addEventListener !== 'function') return;
    this._onEvent = (e) => this.observe(e.type);
    for (const t of EVENTS) next.addEventListener(t, this._onEvent);
    this._tracks = next.textTracks && typeof next.textTracks.addEventListener === 'function' ? next.textTracks : null;
    if (this._tracks) {
      this._tracks.addEventListener('change', this._onEvent);
      this._tracks.addEventListener('addtrack', this._onEvent);
    }
    this.observe('bind');
    this.loadWave();
  }

  unbind() {
    if (this._media && this._onEvent) {
      for (const t of EVENTS) this._media.removeEventListener(t, this._onEvent);
      if (this._tracks) {
        this._tracks.removeEventListener('change', this._onEvent);
        this._tracks.removeEventListener('addtrack', this._onEvent);
      }
    }
    this._media = null;
    this._tracks = null;
    this._onEvent = null;
  }

  /* Every media event lands here. Tracking happens whether or not the player
   * is on screen; only the drawing waits for it to be seen. */
  observe(type) {
    const m = this._media;
    if (!m) return;
    const now = OvPlayer.now();
    if (type === 'bind') this._intent = !m.paused;
    // Play beginning restarts both silences: no frame is owed while buffering.
    if (type === 'play' || type === 'playing') {
      this._intent = true;
      this._blocked = false;
      this._lastAdvance = now;
      if (this._lastFrame !== null) this._lastFrame = now;
    }
    if (type === 'pause' || type === 'ended' || type === 'emptied') this._intent = false;
    if (type === 'pause' || type === 'ended' || type === 'seeking') this._hasPlayed = false;
    if (type === 'emptied') this.resetTracking();
    if (type === 'stalled') this._netStalled = true;
    if (type === 'progress' || type === 'playing' || type === 'canplay') this._netStalled = false;
    if (type === 'seeked') {
      this._lastAdvance = now;
      if (this._lastFrame !== null) this._lastFrame = now;
    }
    if (type === 'loadedmetadata') this.loadWave();

    const t = Number(m.currentTime);
    if (this._lastTime === null || t !== this._lastTime) {
      if (this._lastTime !== null && !m.paused && !m.seeking) this._lastAdvance = now;
      this._lastTime = t;
    }
    const q = this.quality();
    if (q) {
      if (this._frames === null || q.totalVideoFrames !== this._frames) {
        this._frames = q.totalVideoFrames;
        this._lastFrame = now;
      }
    }
    const seek = ranges(m.seekable);
    const edge = seek.length ? seek[seek.length - 1][1] : null;
    if (edge !== this._edge) { this._edge = edge; this._lastEdge = now; }

    if (!this._built || !this.isConnected) return;
    if (isSeen(this)) this.draw();
    else this.account(this.verdict(now).state, now);
  }

  /* ---- the controls: each one asks ------------------------------------ */

  async requestPlay() {
    const m = this._media;
    if (!m) return;
    this._intent = true;
    this._blocked = false;
    this._lastAdvance = OvPlayer.now();
    this.draw();
    try {
      await m.play();
    } catch (err) {
      if (err && err.name === 'AbortError') return;   // a later pause or load interrupted it
      this._blocked = true;
      this._intent = false;
      this._blockedWhy = (err && err.name) || 'refused';
      this.draw();
    }
  }

  requestPause() {
    const m = this._media;
    if (!m) return;
    this._intent = false;
    m.pause();
    this.draw();
  }

  toggle() { if (this._intent) this.requestPause(); else this.requestPlay(); }

  /* The bar's scale: 0 to the duration, or the seekable window of a live
   * stream. Null when there is nothing to seek within. */
  scale() {
    const m = this._media;
    if (!m) return null;
    const d = Number(m.duration);
    const isLive = d === Infinity || this.hasAttribute('live');
    const seek = ranges(m.seekable);
    if (isLive) return seek.length ? [seek[0][0], seek[seek.length - 1][1]] : null;
    return d > 0 && Number.isFinite(d) ? [0, d] : null;
  }

  /* A seek target held inside what can really be sought: the seekable
   * ranges when the media reports them, the scale otherwise. */
  seekTo(t) {
    const m = this._media;
    const sc = this.scale();
    if (!m || !sc) { this.say(`${this.labelText()}: nothing to seek within`); return false; }
    const seek = ranges(m.seekable);
    let target = Math.max(sc[0], Math.min(sc[1], t));
    if (seek.length && !inside(seek, target)) {
      let best = null;
      for (const [a, b] of seek) {
        for (const edge of [a, b]) if (best === null || Math.abs(edge - target) < Math.abs(best - target)) best = edge;
      }
      target = best;
    }
    m.currentTime = target;
    this.draw();
    return true;
  }

  skip(d) { const m = this._media; if (m) this.seekTo(Number(m.currentTime) + d); }

  goLive() {
    const m = this._media;
    const edge = this._edge;
    if (!m || edge === null) return;
    m.currentTime = Math.max(0, edge - LIVE_SYNC_COUNT * this.targetDuration());
    this.draw();
  }

  cycleRate() {
    const m = this._media;
    if (!m) return;
    const r = Number(m.playbackRate) || 1;
    const next = RATES.find((x) => x > r + 1e-6) ?? RATES[0];
    m.playbackRate = next;
    this.draw();
  }

  toggleLoop() { const m = this._media; if (m) { m.loop = !m.loop; this.draw(); } }

  toggleMute() { const m = this._media; if (m) { m.muted = !m.muted; this.draw(); } }

  setVolume(v) {
    const m = this._media;
    if (!m) return;
    m.volume = Math.max(0, Math.min(1, v));
    if (m.volume > 0 && m.muted) m.muted = false;
    this.draw();
  }

  captionTracks() {
    const list = this._media && this._media.textTracks;
    if (!list || typeof list.length !== 'number') return [];
    const out = [];
    for (let i = 0; i < list.length; i++) {
      const tr = list[i];
      if (tr && (tr.kind === 'captions' || tr.kind === 'subtitles')) out.push(tr);
    }
    return out;
  }

  /* Off, then each caption track in turn, then off. */
  cycleCaptions() {
    const tracks = this.captionTracks();
    if (!tracks.length) { this.say(`${this.labelText()}: no captions`); return; }
    const on = tracks.findIndex((tr) => tr.mode === 'showing');
    tracks.forEach((tr) => { tr.mode = 'disabled'; });
    if (on + 1 < tracks.length) tracks[on + 1].mode = 'showing';
    this.draw();
  }

  canPip() {
    const m = this._media;
    return !!m && m.localName === 'video' && typeof m.requestPictureInPicture === 'function'
      && document.pictureInPictureEnabled === true && !m.disablePictureInPicture;
  }

  async togglePip() {
    if (!this.canPip()) return;
    try {
      if (document.pictureInPictureElement === this._media) await document.exitPictureInPicture();
      else await this._media.requestPictureInPicture();
    } catch (err) { this.say(`${this.labelText()}: picture in picture refused`); }
    this.draw();
  }

  canFull() { return typeof this.requestFullscreen === 'function' && document.fullscreenEnabled === true; }

  async toggleFull() {
    if (!this.canFull()) return;
    try {
      if (document.fullscreenElement === this) await document.exitFullscreen();
      else await this.requestFullscreen();
    } catch (err) { this.say(`${this.labelText()}: full screen refused`); }
    this.draw();
  }

  onKey(e) {
    if (e.defaultPrevented || e.metaKey || e.ctrlKey || e.altKey) return;
    const tg = e.target;
    if (tg && tg.localName === 'input' && /^Arrow/.test(e.key)) return;       // the sliders own their arrows
    if (tg && tg.localName === 'button' && (e.key === ' ' || e.key === 'Enter')) return;
    const k = e.key.length === 1 ? e.key.toLowerCase() : e.key;
    const m = this._media;
    if (!m) return;
    if (k === ' ' || k === 'k') this.toggle();
    else if (k === 'j') this.skip(-SKIP);
    else if (k === 'l') this.skip(SKIP);
    else if (k === 'ArrowLeft') this.skip(-5);
    else if (k === 'ArrowRight') this.skip(5);
    else if (k === 'ArrowUp') this.setVolume(Number(m.volume) + 0.1);
    else if (k === 'ArrowDown') this.setVolume(Number(m.volume) - 0.1);
    else if (k === 'm') this.toggleMute();
    else if (k === 'c') this.cycleCaptions();
    else if (k === 'f') this.toggleFull();
    else return;
    e.preventDefault();
  }

  /* What is under a point of the bar: said, not guessed. */
  where(t) {
    const m = this._media;
    if (!m) return '';
    if (inside(ranges(m.played), t)) return 'PLAYED';
    if (inside(ranges(m.buffered), t)) return 'BUFFERED';
    return 'NOT BUFFERED';
  }

  hover(clientX) {
    const sc = this.scale();
    const r = this.$.bar.getBoundingClientRect();
    if (!sc || r.width <= 0) { this.$.tip.hidden = true; return; }
    const f = Math.max(0, Math.min(1, (clientX - r.left) / r.width));
    const t = sc[0] + f * (sc[1] - sc[0]);
    setText(this.$.tip, `${clock(t)} · ${this.where(t)}`);
    setAttr(this.$.tip, 'style', `left:${pct(f)}`);
    setAttr(this.$.tip, 'data-ov-where', this.where(t).toLowerCase().replace(' ', '-'));
    this.$.tip.hidden = false;
  }

  /* ---- the waveform: the file's own, or none ------------------------- */

  async loadWave() {
    const m = this._media;
    if (!this.hasAttribute('waveform') || !m) return;
    const src = m.currentSrc || m.src;
    if (!src || (this._wave && this._wave.src === src) || this._waveLoading === src) return;
    this._waveLoading = src;
    try {
      const { data, seconds } = await OvPlayer.decode(src);
      const step = Math.max(1, Math.floor(data.length / PEAKS));
      let top = '';
      let bottom = '';
      for (let i = 0; i < PEAKS; i++) {
        let hi = 0;
        for (let j = i * step, end = Math.min(data.length, (i + 1) * step); j < end; j++) {
          const v = Math.abs(data[j]);
          if (v > hi) hi = v;
        }
        const y = Math.min(1, hi) * 19;
        top += `${i ? 'L' : 'M'}${i} ${(20 - y).toFixed(1)}`;
        bottom = `L${i} ${(20 + y).toFixed(1)}${bottom}`;
      }
      this._wave = { src, d: `${top}${bottom}Z`, seconds };
      this._waveError = null;
    } catch (err) {
      this._wave = null;
      this._waveError = src;
    }
    this._waveLoading = null;
    this.draw();
  }

  /* ---- the door ------------------------------------------------------- */

  num(raw, min) {
    const v = Number(raw);
    return raw !== null && raw !== '' && Number.isFinite(v) && v >= min ? v : null;
  }

  freeze() { return this.num(this.getAttribute('freeze'), 0.01) ?? FREEZE_DEFAULT; }
  targetDuration() { return this.num(this.getAttribute('target-duration'), 0.1) ?? TARGET_DEFAULT; }
  liveTolerance() {
    return this.num(this.getAttribute('live-tolerance'), 0)
      ?? (LIVE_SYNC_COUNT + 1) * this.targetDuration();
  }
  labelText() { return this.getAttribute('label') || 'media'; }

  /* ---- what is true right now ----------------------------------------- */

  state(now) {
    const m = this._media;
    if (!m) return 'none';
    if (m.error) return 'error';
    if (this._blocked) return 'blocked';
    if (Number(m.readyState) === 0 && !this._intent) return 'empty';
    if (m.ended) return 'ended';
    if (m.seeking) return 'seeking';
    if (m.paused) return this._intent ? 'buffering' : 'paused';
    if (Number(m.readyState) < HAVE_FUTURE_DATA) return this._netStalled ? 'stalled' : 'buffering';
    if (Number(m.playbackRate) === 0) return 'held';
    const freezeMs = this.freeze() * 1000;
    if (this._lastAdvance !== null && now - this._lastAdvance > freezeMs) return 'frozen';
    /* MUTANT */
    return 'playing';
  }

  verdict(now) {
    const m = this._media;
    const state = this.state(now);
    const duration = m ? Number(m.duration) : NaN;
    const isLive = !!m && (duration === Infinity || this.hasAttribute('live'));
    const seek = m ? ranges(m.seekable) : [];
    const edge = seek.length ? seek[seek.length - 1][1] : null;
    const at = m ? Number(m.currentTime) : NaN;
    const behind = edge !== null && Number.isFinite(at) ? Math.max(0, edge - at) : null;
    const edgeStale = isLive && edge !== null && this._lastEdge !== null
      && now - this._lastEdge > LIVE_SYNC_COUNT * this.targetDuration() * 1000;
    const nearEdge = behind !== null && behind <= this.liveTolerance();
    const liveClaim = isLive && state === 'playing' && nearEdge && !edgeStale;

    let why = '';
    if (state === 'none') why = 'NO MEDIA ATTACHED';
    else if (state === 'error') why = `MEDIA ERROR: ${ERRORS[m.error.code] || 'UNKNOWN'}${m.error.message ? ` · ${m.error.message}` : ''}`;
    else if (state === 'blocked') why = `PLAY REFUSED BY THE BROWSER (${this._blockedWhy}) · NOTHING IS PLAYING`;
    else if (state === 'empty') why = 'NOTHING LOADED · NO PICTURE, NO POSITION';
    else if (state === 'buffering') why = `BUFFERING · PLAY ASKED FOR, NO DATA PAST ${clock(at)}`;
    else if (state === 'stalled') why = `STALLED · THE NETWORK HAS STOPPED DELIVERING DATA${this._stallFrom !== null ? ` · SINCE ${hms(this._stallFrom)}` : ''}`;
    else if (state === 'frozen') why = `FROZEN · NOT PAUSED, THE CLOCK STOPPED AT ${clock(at)} · SINCE ${hms(this._lastAdvance)}`;
    else if (state === 'picture-frozen') why = `PICTURE FROZEN · THE CLOCK RUNS, NO NEW FRAME SINCE ${hms(this._lastFrame)}`;
    else if (state === 'held') why = 'PLAYBACK RATE IS 0 · NOT ADVANCING';
    else if (isLive && edge === null) why = 'LIVE EDGE UNKNOWN · NO LIVE CLAIM IS MADE';
    else if (isLive && edgeStale) why = 'LIVE EDGE NOT MOVING · THE STREAM MAY HAVE STOPPED UPDATING';
    else if (isLive && !nearEdge) why = `BEHIND THE LIVE EDGE BY ${clock(behind)} · THIS IS NOT LIVE`;
    else if (isLive && state === 'paused') why = 'PAUSED · FALLING BEHIND THE LIVE EDGE';
    else if (!isLive && state !== 'ended' && !(duration > 0 && Number.isFinite(duration))) why = 'NO DURATION YET · NOTHING TO SEEK WITHIN';

    return { state, duration, isLive, seek, edge, at, behind, edgeStale, nearEdge, liveClaim, why };
  }

  /* Stall episodes: playback that had started and then stopped moving.
   * Counted on entry, timed to exit. A freeze started when the clock last
   * moved, not when noticed. The wait before playback first begins, and the
   * wait after a seek, are shown as BUFFERING but are not stalls: nothing
   * that was playing was interrupted. */
  account(state, now) {
    if (state === 'playing') this._hasPlayed = true;
    const stalling = this._intent && this._hasPlayed && STALL_STATES.has(state);
    if (stalling && this._stallFrom === null) {
      this._stalls += 1;
      this._stallFrom = state === 'frozen' && this._lastAdvance !== null ? this._lastAdvance + this.freeze() * 1000
        : state === 'picture-frozen' && this._lastFrame !== null ? this._lastFrame + this.freeze() * 1000
          : now;
    } else if (!stalling && this._stallFrom !== null) {
      this._stallMs += Math.max(0, now - this._stallFrom);
      this._stallFrom = null;
    }
  }

  get report() {
    const now = OvPlayer.now();
    const v = this.verdict(now);
    const q = this.quality();
    return {
      state: v.state, live: v.liveClaim, behind: v.isLive ? v.behind : null,
      stalls: this._stalls, stallSeconds: (this._stallMs + (this._stallFrom === null ? 0 : now - this._stallFrom)) / 1000,
      dropped: q ? q.droppedVideoFrames : null, frames: q ? q.totalVideoFrames : null,
      demo: this.hasAttribute('demo'),
    };
  }

  quality() {
    const m = this._media;
    if (!m || typeof m.getVideoPlaybackQuality !== 'function') return null;
    const q = m.getVideoPlaybackQuality();
    return q && Number.isFinite(q.totalVideoFrames) ? q : null;
  }

  /* ---- timers --------------------------------------------------------- */

  unschedule() {
    clearTimeout(this._timer);
    this._timer = null;
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
  }

  /* One timer, for the next moment a silence becomes a claim: the clock
   * passing `freeze`, the frame count passing `freeze`, or a live edge
   * standing still for three target durations. */
  schedule(v, now) {
    if (this._timer || this._unarrive) return;
    if (v.state !== 'playing') return;
    const freezeMs = this.freeze() * 1000;
    const dues = [];
    if (this._lastAdvance !== null) dues.push(this._lastAdvance + freezeMs);
    if (this._lastFrame !== null) dues.push(this._lastFrame + freezeMs);
    if (v.isLive && this._lastEdge !== null && !v.edgeStale) dues.push(this._lastEdge + LIVE_SYNC_COUNT * this.targetDuration() * 1000);
    if (!dues.length) return;
    const due = Math.min(...dues);
    // ⚠️ After arrival whenArrived() runs this at once and returns a no-op;
    // keeping that no-op would block every later timer, so it is kept only
    // while the page is still arriving.
    let started = false;
    const off = whenArrived(() => {
      started = true;
      this._unarrive = null;
      this._timer = setTimeout(() => { this._timer = null; this.draw(); }, Math.max(0, due - now) + 20);
    });
    if (!started) this._unarrive = off;
  }

  /* ---- drawing -------------------------------------------------------- */

  build() {
    this._built = true;
    const existing = [...this.querySelectorAll(':scope > video, :scope > audio')];
    const btn = (c, label) => `<button class="ov-btn ov-player__${c}" type="button" aria-label="${label}" title="${label}">`
      + '<span class="ov-player__icon" aria-hidden="true"></span><span class="ov-player__word"></span></button>';
    this.innerHTML = '<div class="ov-player__head">'
      + '<span class="ov-player__label"></span>'
      + '<span class="ov-player__live"></span>'
      + '<span class="ov-player__state"></span></div>'
      + '<div class="ov-player__frame"><div class="ov-player__veil"></div>'
      + `<button class="ov-btn ov-player__big" type="button" aria-label="play" title="play" hidden><span class="ov-player__icon" aria-hidden="true" data-ov-icon="play"></span></button></div>`
      + '<div class="ov-player__bar">'
      + '<div class="ov-player__track">'
      + '<svg class="ov-player__wave" viewBox="0 0 400 40" preserveAspectRatio="none" aria-hidden="true"><path d=""/></svg>'
      + '<div class="ov-player__window"></div>'
      + '<div class="ov-player__bufs"></div>'
      + '<div class="ov-player__played"></div>'
      + '<div class="ov-player__edge"></div>'
      + '<div class="ov-player__head-mark"></div></div>'
      + '<input class="ov-player__seek" type="range" min="0" max="1" step="0.1" value="0" aria-label="seek">'
      + '<span class="ov-player__tip" hidden></span>'
      + '</div>'
      + '<div class="ov-player__controls">'
      + '<div class="ov-player__group">'
      + btn('back', `back ${SKIP} seconds`) + btn('play', 'play') + btn('fwd', `forward ${SKIP} seconds`)
      + '<span class="ov-player__time"></span></div>'
      + '<div class="ov-player__group ov-player__group--end">'
      + '<button class="ov-btn ov-player__golive" type="button"><span>GO TO LIVE</span></button>'
      + btn('rate', 'playback rate') + btn('loop', 'loop') + btn('cc', 'captions')
      + `<span class="ov-player__nocc" title="no captions"><span class="ov-player__icon" aria-hidden="true" data-ov-icon="nocc"></span><span class="ov-player__word">NO CAPTIONS</span></span>`
      + btn('mute', 'mute')
      + '<input class="ov-slider ov-player__vol" type="range" min="0" max="1" step="0.05" value="1" aria-label="volume">'
      + btn('pip', 'picture in picture') + btn('full', 'full screen')
      + '</div></div>'
      + '<div class="ov-player__counts"></div>'
      + '<div class="ov-player__why"></div>'
      + '<div class="ov-player__demo"></div>'
      + '<span class="ov-player__say" aria-live="polite"></span>';
    const q = (c) => this.querySelector(`.ov-player__${c}`);
    this.$ = {};
    for (const c of ['label', 'live', 'state', 'frame', 'veil', 'bar', 'track', 'wave', 'window', 'bufs', 'played',
      'edge', 'seek', 'tip', 'back', 'play', 'fwd', 'time', 'golive', 'rate', 'loop', 'cc', 'nocc', 'mute', 'vol',
      'pip', 'full', 'big', 'counts', 'why', 'demo', 'say']) this.$[c] = q(c);
    this.$.mark = q('head-mark');
    for (const m of existing) this.$.frame.prepend(m);

    const $ = this.$;
    $.play.addEventListener('click', () => this.toggle());
    $.big.addEventListener('click', () => this.requestPlay());
    $.back.addEventListener('click', () => this.skip(-SKIP));
    $.fwd.addEventListener('click', () => this.skip(SKIP));
    $.golive.addEventListener('click', () => this.goLive());
    $.rate.addEventListener('click', () => this.cycleRate());
    $.loop.addEventListener('click', () => this.toggleLoop());
    $.cc.addEventListener('click', () => this.cycleCaptions());
    $.mute.addEventListener('click', () => this.toggleMute());
    $.pip.addEventListener('click', () => this.togglePip());
    $.full.addEventListener('click', () => this.toggleFull());
    $.vol.addEventListener('input', () => this.setVolume(Number($.vol.value)));
    $.seek.addEventListener('input', () => this.seekTo(Number($.seek.value)));
    $.bar.addEventListener('pointermove', (e) => this.hover(e.clientX));
    $.bar.addEventListener('pointerleave', () => { $.tip.hidden = true; });
    this.addEventListener('keydown', (e) => this.onKey(e));
    // Focusable for the keyboard unless the page chose otherwise. Checked
    // without naming the attribute: tools/api.py reads every literal attribute
    // read as this element's API, and tabindex belongs to every element.
    if (!this.getAttributeNames().includes('tabindex')) this.tabIndex = 0;
  }

  draw() {
    if (!this._built) return;
    const now = OvPlayer.now();
    const v = this.verdict(now);
    this.account(v.state, now);
    this.schedule(v, now);
    const m = this._media;
    const $ = this.$;

    setAttr(this, 'data-ov-media', v.state);
    this.toggleAttribute('data-ov-live-claim', v.liveClaim);
    this.toggleAttribute('data-ov-intent', this._intent);
    this.toggleAttribute('data-ov-audio', !!m && m.localName === 'audio');
    setText($.label, this.labelText());
    setText($.state, WORD[v.state]);

    // The picture: covered, and named, whenever it is not playback.
    // No picture, no well: an empty frame would read as a dead picture.
    const hasPicture = m instanceof Node && this.contains(m) && m.localName === 'video';
    $.frame.hidden = !hasPicture;
    // icons (the default), overlay (over the picture; icons when there is none), or words.
    const mode = ['words', 'overlay'].includes(this.getAttribute('controls')) ? this.getAttribute('controls') : 'icons';
    setAttr(this, 'data-ov-controls', mode === 'overlay' && !hasPicture ? 'icons' : mode);
    // The big play only offers to start: never over playback, never over a play already asked for.
    $.big.hidden = !hasPicture || this._intent;
    setText($.veil, v.state === 'playing' ? '' : WORD[v.state]);

    // LIVE, with its distance, or the reason there is no LIVE.
    if (!v.isLive) setText($.live, '');
    else if (v.liveClaim) setText($.live, `LIVE −${clock(v.behind)}`);
    else if (v.edge === null) setText($.live, 'LIVE EDGE UNKNOWN');
    else setText($.live, `NOT LIVE · −${clock(v.behind)}`);
    $.golive.hidden = !(v.isLive && v.edge !== null && !v.nearEdge);

    // The bar.
    const sc = this.scale();
    $.track.hidden = !sc;
    $.seek.hidden = !sc;
    $.back.hidden = !sc;
    $.fwd.hidden = !sc;
    if (!sc) $.tip.hidden = true;
    if (sc) {
      const [lo, hi] = sc;
      $.bar.removeAttribute('data-ov-refusal');
      const x = (t) => (t - lo) / (hi - lo);
      const segs = (list, cls) => list.map(([a, b]) => `<i class="${cls}" style="left:${pct(x(a))};width:${pct(x(b) - x(a))}"></i>`).join('');
      const bufHtml = segs(ranges(m.buffered), 'ov-player__buf');
      if ($.bufs._html !== bufHtml) { $.bufs.innerHTML = bufHtml; $.bufs._html = bufHtml; }
      const playedHtml = segs(ranges(m.played), 'ov-player__seg');
      if ($.played._html !== playedHtml) { $.played.innerHTML = playedHtml; $.played._html = playedHtml; }
      setAttr($.mark, 'style', `left:${pct(x(v.at))}`);
      $.edge.hidden = !v.isLive;
      if (v.isLive) setAttr($.edge, 'style', `left:${pct(x(hi - this.liveTolerance()))};width:${pct(x(hi) - x(hi - this.liveTolerance()))}`);
      setAttr($.mark, 'data-ov-moving', v.state === 'playing' ? 'yes' : 'no');
      $.seek.min = String(lo);
      $.seek.max = String(hi);
      if (document.activeElement !== $.seek && Number.isFinite(v.at)) $.seek.value = String(v.at);
    } else {
      setAttr($.bar, 'data-ov-refusal', !m ? 'no media' : v.isLive ? 'no seekable range' : 'no duration: nothing to seek within');
    }
    // The waveform, only from this file decoded, and only on a recording.
    const wave = this.hasAttribute('waveform') && this._wave && m && this._wave.src === (m.currentSrc || m.src) && sc && !v.isLive;
    setAttr($.wave.firstChild, 'd', wave ? this._wave.d : '');
    $.wave.hidden = !wave;

    // Each button carries an icon and its word; the version decides which shows.
    const word = (b, t) => setText(b.querySelector('.ov-player__word'), t);
    const icon = (b, name) => {
      const slot = b.querySelector('.ov-player__icon');
      if (slot.dataset.ovIcon !== name) slot.dataset.ovIcon = name;
    };
    const label = (b, t) => { setAttr(b, 'aria-label', t); setAttr(b, 'title', t); };

    // Play asks; the icon says what is true. Pause is only drawn over playback.
    const pending = this._intent && v.state !== 'playing';
    $.play.disabled = !m;
    label($.play, this._intent ? (pending ? 'cancel play' : 'pause') : 'play');
    icon($.play, this._intent ? (pending ? 'pending' : 'pause') : 'play');
    word($.play, this._intent ? (v.state === 'playing' ? '▮▮ PAUSE' : '× CANCEL PLAY') : '▶ PLAY');
    setAttr($.play, 'data-ov-pending', pending ? 'yes' : 'no');
    icon($.back, 'back');
    word($.back, `−${SKIP}`);
    icon($.fwd, 'fwd');
    word($.fwd, `+${SKIP}`);

    // Options. Absent, never inert.
    const rate = m ? Number(m.playbackRate) : 1;
    for (const b of [$.rate, $.loop, $.mute, $.vol]) b.hidden = !m;
    word($.rate, rateText(Number.isFinite(rate) ? rate : 1));
    $.loop.hidden = !m || v.isLive;
    icon($.loop, 'loop');
    word($.loop, m && m.loop ? 'LOOP ON' : 'LOOP OFF');
    setAttr($.loop, 'aria-pressed', m && m.loop ? 'true' : 'false');
    const tracks = this.captionTracks();
    $.cc.hidden = !tracks.length;
    // Over the picture the controls sit where captions land, and a caption
    // under a control is a caption nobody can read (seen in real Chrome). The
    // cues are lifted clear while overlaid and put back when not; only cues
    // left on automatic placement are touched, never an author's own position.
    // Six lines up: the bar and controls are about four caption lines tall, and
    // four put the caption exactly behind them (measured in real Chrome). A cue
    // already on screen is not redrawn when it moves, so a showing track is
    // re-shown once after its cues move.
    const lift = this.dataset.ovControls === 'overlay';
    for (const tr of tracks) {
      if (!tr.cues) continue;
      let moved = false;
      for (const c of tr.cues) {
        if (lift && c.line === 'auto') { c.line = -6; c._ovLifted = true; moved = true; } else if (!lift && c._ovLifted) { c.line = 'auto'; c._ovLifted = false; moved = true; }
      }
      if (moved && tr.mode === 'showing') { tr.mode = 'hidden'; tr.mode = 'showing'; }
    }
    $.nocc.hidden = !m || m.localName === 'audio' || tracks.length > 0;
    const showing = tracks.find((tr) => tr.mode === 'showing');
    icon($.cc, showing ? 'ccOn' : 'cc');
    word($.cc, showing ? `CC ${(showing.language || showing.label || 'ON').toUpperCase()}` : 'CC OFF');
    label($.cc, showing ? `captions on, ${showing.label || showing.language || 'track'}` : 'captions off');
    setAttr($.cc, 'aria-pressed', showing ? 'true' : 'false');
    const vol = m ? Number(m.volume) : 1;
    const muted = !!m && (m.muted || vol === 0);
    icon($.mute, muted ? 'muted' : vol < 0.5 ? 'vol1' : 'vol2');
    word($.mute, muted ? 'MUTED' : `VOL ${Math.round(vol * 100)}`);
    label($.mute, muted ? 'muted, unmute' : `volume ${Math.round(vol * 100)}%, mute`);
    setAttr($.mute, 'aria-pressed', muted ? 'true' : 'false');
    if (m && document.activeElement !== $.vol) $.vol.value = String(m.muted ? 0 : vol);
    $.pip.hidden = !this.canPip();
    const inPip = !!document.pictureInPictureElement && document.pictureInPictureElement === m;
    icon($.pip, 'pip');
    word($.pip, inPip ? 'PIP ON' : 'PIP');
    setAttr($.pip, 'aria-pressed', inPip ? 'true' : 'false');
    $.full.hidden = !this.canFull();
    const isFull = document.fullscreenElement === this;
    icon($.full, isFull ? 'unfull' : 'full');
    word($.full, isFull ? 'EXIT FULL' : 'FULL');
    label($.full, isFull ? 'exit full screen' : 'full screen');

    // Time, with the rate beside it whenever the rate is not 1.
    const rq = m && rate !== 1 ? ` · ${rateText(rate)}` : '';
    setText($.time, !m ? '' : v.isLive ? (v.edge === null ? `${clock(v.at)} · EDGE UNKNOWN${rq}` : `−${clock(v.behind)} FROM EDGE${rq}`)
      : `${clock(v.at)} / ${sc ? clock(sc[1]) : '-:--'}${rq}`);

    const q = this.quality();
    // Closed stalls are totalled; an open one is said as OPEN, never as a running figure.
    const closed = this._stallMs / 1000;
    const stallText = `STALLS ${this._stalls}${closed > 0 ? ` · ${closed.toFixed(1)}s` : ''}${this._stallFrom !== null ? ' · 1 OPEN' : ''}`;
    const frames = !m ? '' : q
      ? `DROPPED ${q.droppedVideoFrames} / ${q.totalVideoFrames}`
      : m.localName === 'audio' ? '' : 'FRAMES NOT REPORTED';
    const waveNote = this.hasAttribute('waveform') && m && this._waveError === (m.currentSrc || m.src) ? ' · WAVEFORM UNAVAILABLE' : '';
    setText($.counts, !m ? '' : `${frames}${frames ? ' · ' : ''}${stallText}${waveNote}`);
    this.toggleAttribute('data-ov-dropping', !!q && q.droppedVideoFrames > 0);

    setText($.why, v.why);
    setText($.demo, this.hasAttribute('demo') ? 'DEMONSTRATION MEDIA · NOT A LIVE FEED' : '');

    this.setAttribute('role', 'group');
    this.setAttribute('aria-label', `${this.labelText()}, ${WORD[v.state].toLowerCase()}`
      + `${v.liveClaim ? `, live, ${Math.round(v.behind)} seconds from the edge` : ''}${v.why ? `. ${v.why.toLowerCase()}` : ''}`);

    if (v.state !== this._state) {
      const previous = this._state;
      this._state = v.state;
      if (previous !== null) this.say(`${this.labelText()}: ${WORD[v.state].toLowerCase()}${v.why ? `, ${v.why.toLowerCase()}` : ''}`);
      this.dispatchEvent(new CustomEvent('ov:player', {
        bubbles: true, detail: { state: v.state, previous, live: v.liveClaim },
      }));
    }
  }

  say(text) {
    const region = this.$.say;
    (region._ovSay ||= []).push(text);
    if (region._ovSay.length > 1) return;
    queueMicrotask(() => {
      const all = region._ovSay;
      region._ovSay = [];
      region.textContent = '';
      region.textContent = all.join('. ');
    });
  }
}

define('ov-player', OvPlayer);

export { OvPlayer };
